-- Check-in inspection checklist and vehicle photos (WMS-003, WEB-015). Tables generated by prisma
-- migrate diff, then reviewed; checks, triggers and the pre-check are hand-written.

-- From now on work past the draft stage needs a recorded inspection. Stop with a clear message if
-- existing data would break that rule (no deployment had such jobs when this was written).
DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM workshop.job_card WHERE status NOT IN ('draft', 'cancelled');
  IF n > 0 THEN
    RAISE EXCEPTION 'ERP migration: % job card(s) are past draft without a check-in inspection; contact support before upgrading', n;
  END IF;
END $$;

-- AlterTable
ALTER TABLE "workshop"."job_card" ADD COLUMN     "inspected_at" TIMESTAMPTZ(6),
ADD COLUMN     "inspected_by" UUID;

-- CreateTable
CREATE TABLE "workshop"."inspection_item" (
    "company_id" UUID NOT NULL,
    "job_id" UUID NOT NULL,
    "item_key" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "note" TEXT,

    CONSTRAINT "inspection_item_pkey" PRIMARY KEY ("job_id","item_key")
);

-- CreateTable
CREATE TABLE "workshop"."job_photo" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "company_id" UUID NOT NULL,
    "job_id" UUID NOT NULL,
    "area" TEXT NOT NULL,
    "caption" TEXT,
    "content" BYTEA NOT NULL,
    "thumbnail" BYTEA NOT NULL,
    "width" INTEGER NOT NULL,
    "height" INTEGER NOT NULL,
    "size_bytes" INTEGER NOT NULL,
    "sha256" TEXT NOT NULL,
    "uploaded_by" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "job_photo_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "job_photo_job_id_created_at_idx" ON "workshop"."job_photo"("job_id", "created_at");

-- AddForeignKey
ALTER TABLE "workshop"."inspection_item" ADD CONSTRAINT "inspection_item_company_id_job_id_fkey" FOREIGN KEY ("company_id", "job_id") REFERENCES "workshop"."job_card"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "workshop"."job_photo" ADD CONSTRAINT "job_photo_company_id_job_id_fkey" FOREIGN KEY ("company_id", "job_id") REFERENCES "workshop"."job_card"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;


ALTER TABLE workshop.job_card
  ADD CONSTRAINT job_inspected_pair CHECK ((inspected_at IS NULL) = (inspected_by IS NULL)),
  ADD CONSTRAINT job_inspected_after_draft CHECK (status IN ('draft', 'cancelled') OR inspected_at IS NOT NULL);

ALTER TABLE workshop.inspection_item
  ADD CONSTRAINT inspection_item_status_valid CHECK (status IN ('ok', 'attention', 'not_checked')),
  ADD CONSTRAINT inspection_item_key_format CHECK (item_key ~ '^[a-z][a-z_]{1,39}$'),
  ADD CONSTRAINT inspection_item_attention_note CHECK (status <> 'attention' OR coalesce(btrim(note), '') <> '');

ALTER TABLE workshop.job_photo
  ADD CONSTRAINT job_photo_area_valid CHECK (area IN ('front', 'rear', 'left', 'right', 'interior', 'odometer', 'damage', 'other')),
  ADD CONSTRAINT job_photo_size CHECK (size_bytes = octet_length(content) AND size_bytes BETWEEN 1 AND 5242880
                                       AND octet_length(thumbnail) BETWEEN 1 AND 262144),
  ADD CONSTRAINT job_photo_dimensions CHECK (width BETWEEN 1 AND 4096 AND height BETWEEN 1 AND 4096),
  ADD CONSTRAINT job_photo_sha256 CHECK (sha256 ~ '^[0-9a-f]{64}$');

-- The checklist is evidence of the condition on arrival: it changes only while the job is a draft.
CREATE OR REPLACE FUNCTION workshop.guard_inspection_draft() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE s text;
BEGIN
  SELECT status INTO s FROM workshop.job_card WHERE id = COALESCE(NEW.job_id, OLD.job_id);
  IF s IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'ERP: the check-in inspection can only change while the job is a draft (job is %)', s
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;
CREATE TRIGGER inspection_item_draft_only BEFORE INSERT OR UPDATE OR DELETE ON workshop.inspection_item
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_inspection_draft();

-- Photos are never edited; they can be removed only while the job is a draft (a mistaken upload).
CREATE TRIGGER job_photo_no_update BEFORE UPDATE ON workshop.job_photo
  FOR EACH ROW EXECUTE FUNCTION platform.forbid_mutation();
CREATE OR REPLACE FUNCTION workshop.guard_photo_delete() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE s text;
BEGIN
  SELECT status INTO s FROM workshop.job_card WHERE id = OLD.job_id;
  IF s IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'ERP: photos are evidence once work is authorised and cannot be removed (job is %)', s
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN OLD;
END;
$$;
CREATE TRIGGER job_photo_delete_draft_only BEFORE DELETE ON workshop.job_photo
  FOR EACH ROW EXECUTE FUNCTION workshop.guard_photo_delete();

ALTER TABLE workshop.job_event DROP CONSTRAINT job_event_kind_valid;
ALTER TABLE workshop.job_event ADD CONSTRAINT job_event_kind_valid CHECK (kind IN (
  'created', 'status', 'assignment', 'task_done', 'task_reopened', 'qc_pass', 'qc_fail', 'note', 'updated',
  'inspection', 'photo_added', 'photo_removed'));
